/**
 * galois.mjs — arithmetic in the finite field GF(2^8) used by AES.
 *
 * The Python original (`pyaes`) ships pre-computed S-box / multiplication
 * tables. This port reproduces the *values* of those tables by deriving them
 * from first principles (FIPS-197 §4), so the only thing hard-coded anywhere in
 * the AES core is the field's reduction polynomial. Nothing here touches
 * `node:crypto`; every operation is plain integer bit math on bytes.
 *
 * Field: GF(2) polynomials modulo the irreducible AES polynomial
 *   m(x) = x^8 + x^4 + x^3 + x + 1   (0x11b)
 *
 * Bytes are ordinary JS numbers in the range 0..255.
 */

/** The AES reduction polynomial, minus its x^8 term (FIPS-197 §4.2). */
const REDUCTION = 0x1b;

/**
 * Multiply a byte by x (i.e. by 0x02) in GF(2^8).
 *
 * A left shift is the polynomial multiplication; if the shift pushed a bit out
 * of the x^7 position the result is reduced modulo m(x) by XORing 0x1b.
 *
 * @param {number} a byte, 0..255
 * @returns {number} byte, 0..255
 */
export function xtime(a) {
  const b = (a & 0xff) << 1;
  return (b & 0x100 ? b ^ REDUCTION : b) & 0xff;
}

/**
 * Multiply two bytes in GF(2^8) (russian-peasant / shift-and-add).
 *
 * Runs in constant iteration count (8) so it stays trivially auditable; it is
 * only ever used at module-load time to build the lookup tables.
 *
 * @param {number} a byte, 0..255
 * @param {number} b byte, 0..255
 * @returns {number} byte, 0..255
 */
export function gmul(a, b) {
  let x = a & 0xff;
  let y = b & 0xff;
  let product = 0;
  for (let i = 0; i < 8; i += 1) {
    if (y & 1) product ^= x;
    y >>= 1;
    x = xtime(x);
  }
  return product & 0xff;
}

/**
 * Multiplicative inverse in GF(2^8).
 *
 * Zero has no inverse; AES defines the S-box so that 0x00 maps to itself, so we
 * follow that convention and return 0 for 0 (FIPS-197 §5.1.1).
 *
 * The table is built once at module load by exhaustive search over the 255
 * non-zero field elements — small, deterministic, and free of any dependency on
 * a hard-coded inverse table.
 *
 * @param {number} a byte, 0..255
 * @returns {number} byte, 0..255
 */
export function ginv(a) {
  return INVERSES[a & 0xff];
}

/** Lazily-free precomputation: 256-entry inverse table, index 0 fixed at 0. */
const INVERSES = (() => {
  const table = new Uint8Array(256);
  for (let a = 1; a < 256; a += 1) {
    if (table[a] !== 0) continue; // already filled in as some earlier pair
    for (let b = 1; b < 256; b += 1) {
      if (gmul(a, b) === 1) {
        table[a] = b;
        table[b] = a; // inversion is an involution
        break;
      }
    }
  }
  return table;
})();

/**
 * errors.mjs — error types raised by the AES core.
 *
 * The Python original raises bare `ValueError`s from inside `pyaes`
 * (`ValueError: Invalid key size`, `ValueError: plaintext block must be
 * 16 bytes`). This layer stays deliberately Python-agnostic: it knows nothing
 * about tracebacks, exit codes or `repr()`. The pyaes shim sitting above it is
 * responsible for translating these classes into the exact CPython-style
 * diagnostics, so the cipher core remains a clean, reusable library.
 */

/**
 * Raised when a key is not 16, 24 or 32 bytes long.
 *
 * The default message matches the text the Python side ultimately reports, but
 * callers may override it.
 */
export class InvalidKeySizeError extends Error {
  /** @param {string} [message] */
  constructor(message = 'Invalid key size') {
    super(message);
    this.name = 'InvalidKeySizeError';
  }
}

/**
 * Raised when a block handed to the cipher is not exactly `BLOCK_SIZE` bytes.
 *
 * The message is always supplied by the caller, because the wording differs by
 * direction upstream (plaintext vs. ciphertext block).
 */
export class InvalidBlockSizeError extends Error {
  /** @param {string} message */
  constructor(message) {
    super(message);
    this.name = 'InvalidBlockSizeError';
  }
}

/**
 * tables.mjs — the AES substitution boxes, round constants and MixColumns
 * multiplication tables, all derived at module load.
 *
 * `pyaes` carries these as literal Python lists. Reproducing the literals by
 * hand would be unverifiable, so instead the S-box is *computed* exactly as
 * FIPS-197 §5.1.1 defines it — multiplicative inverse in GF(2^8) followed by the
 * affine transform — and then checked against known FIPS-197 values. If the
 * derivation is ever wrong the module refuses to load rather than silently
 * producing wrong ciphertext.
 */

import { gmul, ginv, xtime } from './galois.mjs';

/**
 * Rotate a byte left by `n` bits (the `b_i xor b_(i+4) xor ...` shifts in the
 * S-box affine transform are byte rotations).
 *
 * @param {number} b byte, 0..255
 * @param {number} n bit count, 1..7
 * @returns {number} byte, 0..255
 */
function rotl8(b, n) {
  return ((b << n) | (b >>> (8 - n))) & 0xff;
}

/**
 * The AES S-box: y = affine(inv(x)).
 *
 * affine(b) = b ^ rotl(b,1) ^ rotl(b,2) ^ rotl(b,3) ^ rotl(b,4) ^ 0x63
 *
 * @type {Uint8Array}
 */
export const SBOX = (() => {
  const box = new Uint8Array(256);
  for (let x = 0; x < 256; x += 1) {
    const b = ginv(x);
    box[x] = (b ^ rotl8(b, 1) ^ rotl8(b, 2) ^ rotl8(b, 3) ^ rotl8(b, 4) ^ 0x63) & 0xff;
  }
  return box;
})();

/**
 * The inverse S-box, obtained by inverting the permutation above.
 * @type {Uint8Array}
 */
export const INV_SBOX = (() => {
  const box = new Uint8Array(256);
  for (let x = 0; x < 256; x += 1) box[SBOX[x]] = x;
  return box;
})();

/**
 * Round constants. `RCON[i]` (for i >= 1) is x^(i-1) in GF(2^8):
 * 01 02 04 08 10 20 40 80 1b 36. Index 0 is unused padding so that the array is
 * indexed by round number, matching FIPS-197's notation.
 * @type {Uint8Array}
 */
export const RCON = (() => {
  const rcon = new Uint8Array(11);
  let value = 0x01;
  for (let i = 1; i < 11; i += 1) {
    rcon[i] = value;
    value = xtime(value);
  }
  return rcon;
})();

/**
 * Build a 256-entry table of `byte -> gmul(byte, factor)`.
 * @param {number} factor
 * @returns {Uint8Array}
 */
function mulTable(factor) {
  const table = new Uint8Array(256);
  for (let x = 0; x < 256; x += 1) table[x] = gmul(x, factor);
  return table;
}

/** Multiply-by-2 table (MixColumns). @type {Uint8Array} */
export const MUL2 = mulTable(0x02);
/** Multiply-by-3 table (MixColumns). @type {Uint8Array} */
export const MUL3 = mulTable(0x03);
/** Multiply-by-9 table (InvMixColumns). @type {Uint8Array} */
export const MUL9 = mulTable(0x09);
/** Multiply-by-0x0b table (InvMixColumns). @type {Uint8Array} */
export const MUL11 = mulTable(0x0b);
/** Multiply-by-0x0d table (InvMixColumns). @type {Uint8Array} */
export const MUL13 = mulTable(0x0d);
/** Multiply-by-0x0e table (InvMixColumns). @type {Uint8Array} */
export const MUL14 = mulTable(0x0e);

// ---------------------------------------------------------------------------
// Self-verification. These run once, at import time; a failure means the field
// arithmetic or the affine transform is broken and no ciphertext produced by
// this library could be trusted.
// ---------------------------------------------------------------------------

/**
 * @param {boolean} condition
 * @param {string} message
 */
function check(condition, message) {
  if (!condition) throw new Error(`AES table derivation failed: ${message}`);
}

/** Spot values taken from the FIPS-197 §5.1.1 S-box figure. */
const SBOX_KNOWN = [
  [0x00, 0x63],
  [0x01, 0x7c],
  [0x10, 0xca],
  [0x53, 0xed],
  [0x7f, 0xd2],
  [0xff, 0x16],
];

for (const [input, expected] of SBOX_KNOWN) {
  check(
    SBOX[input] === expected,
    `SBOX[0x${input.toString(16).padStart(2, '0')}] === 0x${SBOX[input]
      .toString(16)
      .padStart(2, '0')}, expected 0x${expected.toString(16).padStart(2, '0')}`,
  );
}

for (let i = 0; i < 256; i += 1) {
  check(INV_SBOX[SBOX[i]] === i, `INV_SBOX is not the inverse of SBOX at index ${i}`);
}

check(
  RCON[1] === 0x01 && RCON[8] === 0x80 && RCON[9] === 0x1b && RCON[10] === 0x36,
  'RCON does not match 01 02 04 08 10 20 40 80 1b 36',
);

/**
 * key-schedule.mjs — the AES key expansion (FIPS-197 §5.2).
 *
 * Mirrors what `pyaes.AES.__init__` does when it is handed a key: reject
 * anything that is not 16/24/32 bytes (`ValueError: Invalid key size` upstream),
 * otherwise expand the key into `rounds + 1` round keys.
 *
 * Byte order note: `pyaes` keeps its round keys as 32-bit words and transposes
 * during AddRoundKey. Here each round key is flattened into a Uint8Array(16)
 * whose byte order is identical to the 16-byte input block, so AddRoundKey is a
 * plain 16-way XOR with no transposition anywhere in the hot path.
 */

import { SBOX, RCON } from './tables.mjs';
import { InvalidKeySizeError } from './errors.mjs';

/** AES block size in bytes. Always 16 — Rijndael's larger blocks are not AES. */
export const BLOCK_SIZE = 16;

/**
 * Number of rounds per key length in bytes (FIPS-197 Fig. 4).
 * @type {Map<number, number>}
 */
export const ROUNDS_BY_KEY_SIZE = new Map([
  [16, 10],
  [24, 12],
  [32, 14],
]);

/**
 * True when `byteLength` is a key size AES accepts.
 * @param {number} byteLength
 * @returns {boolean}
 */
export function isValidKeySize(byteLength) {
  return ROUNDS_BY_KEY_SIZE.has(byteLength);
}

/**
 * Apply the S-box to each byte of a 4-byte word, in place.
 * @param {Uint8Array} word
 */
function subWord(word) {
  word[0] = SBOX[word[0]];
  word[1] = SBOX[word[1]];
  word[2] = SBOX[word[2]];
  word[3] = SBOX[word[3]];
}

/**
 * Rotate a 4-byte word one byte left: [a0,a1,a2,a3] -> [a1,a2,a3,a0].
 * @param {Uint8Array} word
 */
function rotWord(word) {
  const first = word[0];
  word[0] = word[1];
  word[1] = word[2];
  word[2] = word[3];
  word[3] = first;
}

/**
 * Expand a cipher key into the AES round keys.
 *
 * @param {Uint8Array} keyBytes 16, 24 or 32 bytes
 * @returns {{ keySize: number, rounds: number, roundKeys: Uint8Array[] }}
 *   `roundKeys` has `rounds + 1` entries, each a fresh Uint8Array(16) in input
 *   block byte order.
 * @throws {InvalidKeySizeError} when the key length is not 16/24/32
 */
export function expandKey(keyBytes) {
  const keySize = keyBytes == null ? -1 : keyBytes.length;
  if (!isValidKeySize(keySize)) throw new InvalidKeySizeError();

  const rounds = /** @type {number} */ (ROUNDS_BY_KEY_SIZE.get(keySize));
  const nk = keySize / 4; // key length in 32-bit words: 4, 6 or 8
  const totalWords = 4 * (rounds + 1); // 44, 52 or 60

  // words[i] is w_i from FIPS-197, stored big-endian as 4 bytes.
  /** @type {Uint8Array[]} */
  const words = new Array(totalWords);

  for (let i = 0; i < nk; i += 1) {
    words[i] = Uint8Array.prototype.slice.call(keyBytes, i * 4, i * 4 + 4);
  }

  for (let i = nk; i < totalWords; i += 1) {
    const temp = words[i - 1].slice();
    if (i % nk === 0) {
      rotWord(temp);
      subWord(temp);
      temp[0] ^= RCON[i / nk];
    } else if (nk > 6 && i % nk === 4) {
      // AES-256 only: an extra SubWord halfway through each key block.
      subWord(temp);
    }
    const prev = words[i - nk];
    const word = new Uint8Array(4);
    word[0] = prev[0] ^ temp[0];
    word[1] = prev[1] ^ temp[1];
    word[2] = prev[2] ^ temp[2];
    word[3] = prev[3] ^ temp[3];
    words[i] = word;
  }

  // Flatten groups of four words into block-ordered 16-byte round keys.
  /** @type {Uint8Array[]} */
  const roundKeys = new Array(rounds + 1);
  for (let r = 0; r <= rounds; r += 1) {
    const roundKey = new Uint8Array(BLOCK_SIZE);
    for (let w = 0; w < 4; w += 1) roundKey.set(words[r * 4 + w], w * 4);
    roundKeys[r] = roundKey;
  }

  return { keySize, rounds, roundKeys };
}
